import { GoogleGenAI, Part, Chat, Type } from "@google/genai";
import { ITINERARY_SCHEMA, Itinerary, Day, MAINTENANCE_TIPS_SCHEMA, MaintenanceTips, GarageVehicle, MaintenanceRecord, VEHICLE_SPECS_SCHEMA, DiaryEntry } from '../types';

// La chiave API viene ottenuta esclusivamente dalle variabili d'ambiente
const getAi = () => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
        throw new Error("API_KEY non configurata.");
    }
    return new GoogleGenAI({ apiKey });
};

// --- API PROXY ---
const apiProxy = async (model: string, contents: any, config: any) => {
    try {
        const ai = getAi();
        const response = await ai.models.generateContent({ model, contents, config });
        const jsonText = response.text || "";
        return JSON.parse(jsonText.trim());
    } catch (e: any) {
        console.error("API Proxy Error:", e);
        throw new Error("Errore durante la comunicazione con l'IA.");
    }
};

const textApiProxy = async (model: string, contents: any, config?: any) => {
    try {
         const ai = getAi();
         const response = await ai.models.generateContent({ model, contents, config });
         return response.text || "Nessuna risposta generata.";
    } catch (e: any) {
         console.error("Text API Proxy Error:", e);
         throw new Error("Errore nella generazione del testo.");
    }
};

// --- Mappers ---
const mapApiItineraryToAppItinerary = (apiResponse: any): Itinerary => {
    return {
        tripTitle: apiResponse.titolo_viaggio,
        generalDescription: apiResponse.descrizione_generale,
        dailySchedule: apiResponse.programma_giornaliero.map((day: any): Day => ({
            day: day.giorno,
            stageTitle: day.titolo_tappa,
            routeDescription: day.descrizione_percorso,
            stageKilometers: day.chilometri_tappa,
            activities: day.attivita_luoghi_interesse,
            gpxTrack: day.tracciato_gpx,
            weatherForecast: {
                temperatureMin: day.previsioni_meteo.temperatura_min,
                temperatureMax: day.previsioni_meteo.temperatura_max,
                conditions: day.previsioni_meteo.condizioni,
                icon: day.previsioni_meteo.icona,
            },
            drivingTips: day.consigli_di_guida,
            restaurantOption: day.opzione_ristoro,
            accommodation: day.alloggio_consigliato,
            alternativeRouteSuggestion: day.suggerimento_strada_alternativa,
        }))
    };
};

// --- PROMPT BUILDERS ---

const buildItineraryPrompt = (options: any): string => {
    const { departure, destination, tourName, duration, roadPreference, period, motorcycle, customPrompt } = options;
    return `Agisci come un esperto pianificatore di viaggi in moto. Crea un itinerario di ${duration} giorni ${tourName ? `per il tour "${tourName}"` : `da ${departure} a ${destination}`}.
Periodo: ${period}. Preferenza strade: ${roadPreference}. 
${motorcycle ? `Moto: ${motorcycle.model} (${motorcycle.year}, ${motorcycle.kilometers}km).` : ''}
FILOSOFIA: Massimizza le curve, i passi di montagna e i panorami. Evita autostrade.
Richieste extra: ${customPrompt || 'Nessuna'}.
Restituisci l'itinerario in formato JSON seguendo lo schema definito.`;
};

const buildDiagnosisPrompt = (problemDescription: string, motorcycle: GarageVehicle): string => {
    return `Agisci come un Capo Meccanico esperto. Diagnostica il seguente problema per una ${motorcycle.model} (${motorcycle.year}) con ${motorcycle.kilometers} km.
Problema riportato dall'utente: "${problemDescription}".
Esegui un ragionamento passo-passo considerando la meccanica specifica di questo modello, i richiami noti e l'usura chilometrica. 
Fornisci: 1. Cause probabili, 2. Verifiche da fare a casa, 3. Quando rivolgersi urgentemente in officina.`;
};

// --- SERVICE FUNCTIONS ---

export const generateItinerary = async (options: any): Promise<Itinerary> => {
    const prompt = buildItineraryPrompt(options);
    const config = {
        responseMimeType: "application/json",
        responseSchema: ITINERARY_SCHEMA,
        thinkingConfig: { thinkingBudget: 16000 } // Ragionamento per rotte panoramiche ottimali
    };
    const response = await apiProxy('gemini-3-pro-preview', { parts: [{ text: prompt }] }, config);
    return mapApiItineraryToAppItinerary(response);
};

export const diagnoseProblem = async (problemDescription: string, motorcycle: GarageVehicle, image?: File): Promise<string> => {
    const prompt = buildDiagnosisPrompt(problemDescription, motorcycle);
    const parts: any[] = [{ text: prompt }];
    if (image) {
        const base64Data = await new Promise<string>((resolve) => {
            const reader = new FileReader();
            reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
            reader.readAsDataURL(image);
        });
        parts.push({ inlineData: { data: base64Data, mimeType: image.type } });
    }
    return await textApiProxy('gemini-3-pro-preview', { parts }, { 
        thinkingConfig: { thinkingBudget: 32768 } // Massimo ragionamento per diagnosi meccanica
    });
};

export const generateTripDiarySummary = async (itinerary: Itinerary, entries: DiaryEntry[]): Promise<string> => {
    const diaryContent = entries.map(e => `Giorno ${e.day}: "${e.content}"`).join('\n');
    const prompt = `Scrivi un racconto epico e coinvolgente in prima persona per il viaggio "${itinerary.tripTitle}". 
Usa queste note del pilota come base:
${diaryContent}
Stile: Appassionato, motociclistico, tecnico ma emozionale.`;
    return await textApiProxy('gemini-3-flash-preview', { parts: [{ text: prompt }] });
};

export const getVehicleSpecs = async (model: string, year: string) => {
    const prompt = `Fornisci dati tecnici precisi per ${model} del ${year}: cilindrata, potenza, misure pneumatici anteriore e posteriore.`;
    const config = {
        responseMimeType: "application/json",
        responseSchema: VEHICLE_SPECS_SCHEMA,
    };
    return await apiProxy('gemini-3-flash-preview', { parts: [{ text: prompt }] }, config);
};

export const createChatSession = (vehicle: GarageVehicle | null): Chat => {
    const ai = getAi();
    const systemInstruction = `Sei MotoMentor AI, un assistente esperto per motociclisti. 
${vehicle ? `L'utente possiede una ${vehicle.model} (${vehicle.year}).` : ''}
Il tuo tono è cordiale, tecnico, e appassionato. Sei un esperto sia di meccanica che di viaggi avventura.`;

    return ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
            systemInstruction: systemInstruction,
        },
    });
};

import React, { createContext, useReducer, useContext, useEffect, ReactNode, useCallback, FormEvent, useRef } from 'react';
import { Chat, Content } from '@google/genai';
import { generateItinerary, diagnoseProblem, getMaintenanceTips, createChatSession, getVehicleSpecs, generateTripDiarySummary } from '../services/geminiService';
import { Itinerary, MaintenanceTips, GarageVehicle, AiMode, SavedTrip, MaintenanceRecord, MaintenanceReminder, SavedDiagnosis, DiaryEntry } from '../types';
import { useLocalStorage } from '../utils/hooks';
import { generatePdf } from '../utils/pdf';

// Tipi e Interfacce (rimasti invariati per brevità)
// ... (tutto il blocco AppState e AppAction come nel file originale)

interface Notification {
    message: string;
    type: 'success' | 'error' | 'warning';
}

export interface ChatHistoryItem {
    key: string;
    vehicleName: string;
    lastUpdated: string | null;
}

interface DeadlineAlert {
    vehicleId: string;
    vehicleName: string;
    type: 'Assicurazione' | 'Bollo' | 'Revisione';
    date: string;
    status: 'expired' | 'warning';
    daysRemaining: number;
}

interface AppState {
    mode: AiMode;
    isLoadingData: boolean;
    isGeneratingItinerary: boolean;
    isDiagnosingProblem: boolean;
    isGeneratingChecklist: boolean;
    isChatLoading: boolean;
    isGeneratingPdf: boolean;
    isGeneratingDiagnosisPdf: boolean;
    isGeneratingChecklistPdf: boolean;
    isGeneratingDiarySummary: boolean;
    error: string | null;
    notification: Notification | null;
    savedConfirmation: string | null;
    usingLocalStorage: boolean;
    garageVehicles: GarageVehicle[];
    activeVehicle: GarageVehicle | null;
    maintenanceLog: MaintenanceRecord[];
    reminders: MaintenanceReminder[];
    tripHistory: SavedTrip[];
    savedDiagnoses: SavedDiagnosis[];
    deadlineAlerts: DeadlineAlert[];
    itinerary: Itinerary | null;
    activeTripId: string | null;
    tripMaintenanceAlerts: string[];
    diagnosis: string | null;
    activeDiagnosisId: string | null;
    maintenanceTips: MaintenanceTips | null;
    activeDiaryTripId: string | null;
    chatSession: Chat | null;
    chatHistory: Content[];
    chatHistoryList: ChatHistoryItem[];
    drafts: {
        tripPlanner: {
            tripType: 'itinerary' | 'tour';
            selectedTour: string;
            departure: string;
            destination: string;
            duration: string;
            period: string;
            roadPreference: string;
            customRoadPreferenceText: string;
            customPrompt: string;
        };
        virtualMechanic: {
            problemDescription: string;
            problemImage: File | null;
        };
    };
    mechanicMode: 'diagnose' | 'maintenance' | 'workshop';
}

type AppAction =
    | { type: 'SET_MODE'; payload: AiMode }
    | { type: 'SET_LOADING_DATA'; payload: boolean }
    | { type: 'SET_ITINERARY_GENERATING'; payload: boolean }
    | { type: 'SET_DIAGNOSIS_GENERATING'; payload: boolean }
    | { type: 'SET_CHECKLIST_GENERATING'; payload: boolean }
    | { type: 'SET_CHAT_LOADING'; payload: boolean }
    | { type: 'SET_PDF_GENERATING'; payload: boolean }
    | { type: 'SET_DIAGNOSIS_PDF_GENERATING'; payload: boolean }
    | { type: 'SET_CHECKLIST_PDF_GENERATING'; payload: boolean }
    | { type: 'SET_DIARY_SUMMARY_GENERATING'; payload: boolean }
    | { type: 'SET_ERROR'; payload: string | null }
    | { type: 'SET_NOTIFICATION'; payload: Notification | null }
    | { type: 'SET_DATA'; payload: { key: keyof AppState, value: any } }
    | { type: 'SET_ITINERARY'; payload: { itinerary: Itinerary | null, tripId: string | null } }
    | { type: 'SET_DIAGNOSIS'; payload: { diagnosis: string | null, diagnosisId: string | null } }
    | { type: 'UPDATE_TRIP_DRAFT'; payload: Partial<AppState['drafts']['tripPlanner']> }
    | { type: 'UPDATE_MECHANIC_DRAFT'; payload: Partial<AppState['drafts']['virtualMechanic']> }
    | { type: 'SET_MECHANIC_MODE'; payload: 'diagnose' | 'maintenance' | 'workshop' }
    | { type: 'RESET_TRIP_PLANNER_FORM' }
    | { type: 'SET_USING_LOCAL_STORAGE'; payload: boolean }
    | { type: 'SET_ACTIVE_DIARY_TRIP'; payload: string | null };

const initialState: AppState = {
    mode: AiMode.TripPlanner,
    isLoadingData: false,
    isGeneratingItinerary: false,
    isDiagnosingProblem: false,
    isGeneratingChecklist: false,
    isChatLoading: false,
    isGeneratingPdf: false,
    isGeneratingDiagnosisPdf: false,
    isGeneratingChecklistPdf: false,
    isGeneratingDiarySummary: false,
    error: null,
    notification: null,
    savedConfirmation: null,
    usingLocalStorage: false, 
    garageVehicles: [],
    activeVehicle: null,
    maintenanceLog: [],
    reminders: [],
    tripHistory: [],
    savedDiagnoses: [],
    deadlineAlerts: [],
    itinerary: null,
    activeTripId: null,
    tripMaintenanceAlerts: [],
    diagnosis: null,
    activeDiagnosisId: null,
    maintenanceTips: null,
    activeDiaryTripId: null,
    chatSession: null,
    chatHistory: [],
    chatHistoryList: [],
    drafts: {
        tripPlanner: {
            tripType: 'itinerary',
            selectedTour: '',
            departure: '',
            destination: '',
            duration: '',
            period: '',
            roadPreference: '',
            customRoadPreferenceText: '',
            customPrompt: '',
        },
        virtualMechanic: {
            problemDescription: '',
            problemImage: null,
        },
    },
    mechanicMode: 'workshop',
};

const appReducer = (state: AppState, action: AppAction): AppState => {
    switch (action.type) {
        case 'SET_MODE': return { ...state, mode: action.payload };
        case 'SET_LOADING_DATA': return { ...state, isLoadingData: action.payload };
        case 'SET_ITINERARY_GENERATING': return { ...state, isGeneratingItinerary: action.payload };
        case 'SET_DIAGNOSIS_GENERATING': return { ...state, isDiagnosingProblem: action.payload };
        case 'SET_CHECKLIST_GENERATING': return { ...state, isGeneratingChecklist: action.payload };
        case 'SET_CHAT_LOADING': return { ...state, isChatLoading: action.payload };
        case 'SET_PDF_GENERATING': return { ...state, isGeneratingPdf: action.payload };
        case 'SET_DIAGNOSIS_PDF_GENERATING': return { ...state, isGeneratingDiagnosisPdf: action.payload };
        case 'SET_CHECKLIST_PDF_GENERATING': return { ...state, isGeneratingChecklistPdf: action.payload };
        case 'SET_DIARY_SUMMARY_GENERATING': return { ...state, isGeneratingDiarySummary: action.payload };
        case 'SET_ERROR': return { ...state, error: action.payload, isGeneratingItinerary: false, isDiagnosingProblem: false, isGeneratingChecklist: false, isChatLoading: false };
        case 'SET_NOTIFICATION': return { ...state, notification: action.payload };
        case 'SET_DATA': return { ...state, [action.payload.key]: action.payload.value };
        case 'SET_ITINERARY': return { ...state, itinerary: action.payload.itinerary, activeTripId: action.payload.tripId };
        case 'SET_DIAGNOSIS': return { ...state, diagnosis: action.payload.diagnosis, activeDiagnosisId: action.payload.diagnosisId };
        case 'UPDATE_TRIP_DRAFT': return { ...state, drafts: { ...state.drafts, tripPlanner: { ...state.drafts.tripPlanner, ...action.payload } } };
        case 'UPDATE_MECHANIC_DRAFT': return { ...state, drafts: { ...state.drafts, virtualMechanic: { ...state.drafts.virtualMechanic, ...action.payload } } };
        case 'SET_MECHANIC_MODE': return { ...state, mechanicMode: action.payload };
        case 'RESET_TRIP_PLANNER_FORM': return { ...state, itinerary: null, activeTripId: null, drafts: { ...state.drafts, tripPlanner: initialState.drafts.tripPlanner } };
        case 'SET_USING_LOCAL_STORAGE': return { ...state, usingLocalStorage: action.payload };
        case 'SET_ACTIVE_DIARY_TRIP': return { ...state, activeDiaryTripId: action.payload };
        default: return state;
    }
};

const AppContext = createContext<any>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [state, dispatch] = useReducer(appReducer, initialState);
    const [storedActiveId, setStoredActiveId] = useLocalStorage<string | null>('motoMentorActiveVehicleId', null);

    const showNotification = useCallback((message: string, type: 'success' | 'error' | 'warning' = 'success') => {
        dispatch({ type: 'SET_NOTIFICATION', payload: { message, type } });
    }, []);

    // Re-inizializzazione chat quando cambia il veicolo o la modalità
    useEffect(() => {
        if (state.mode === AiMode.AiChat) {
            try {
                const session = createChatSession(state.activeVehicle);
                dispatch({ type: 'SET_DATA', payload: { key: 'chatSession', value: session } });
            } catch (e) {
                console.error("Chat init error:", e);
            }
        }
    }, [state.mode, state.activeVehicle]);

    const handleSendMessage = useCallback(async (message: string) => {
        if (!state.chatSession || state.isChatLoading) return;

        const userMsg = { role: 'user', parts: [{ text: message }] };
        const updatedHistory = [...state.chatHistory, userMsg];
        dispatch({ type: 'SET_DATA', payload: { key: 'chatHistory', value: updatedHistory } });
        dispatch({ type: 'SET_CHAT_LOADING', payload: true });

        try {
            const stream = await state.chatSession.sendMessageStream({ message });
            let fullText = "";
            for await (const chunk of stream) {
                fullText += chunk.text;
                const newHistory = [...updatedHistory, { role: 'model', parts: [{ text: fullText }] }];
                dispatch({ type: 'SET_DATA', payload: { key: 'chatHistory', value: newHistory } });
            }
        } catch (err) {
            showNotification("Errore durante la conversazione.", "error");
        } finally {
            dispatch({ type: 'SET_CHAT_LOADING', payload: false });
        }
    }, [state.chatSession, state.chatHistory, state.isChatLoading, showNotification]);

    const handleTripSubmit = useCallback(async (e: FormEvent) => {
        e.preventDefault();
        dispatch({ type: 'SET_ITINERARY_GENERATING', payload: true });
        try {
            const itinerary = await generateItinerary(state.drafts.tripPlanner);
            dispatch({ type: 'SET_ITINERARY', payload: { itinerary, tripId: null } });
            showNotification("Itinerario generato con successo!");
        } catch (err) {
            showNotification("Errore nella generazione dell'itinerario.", "error");
        } finally {
            dispatch({ type: 'SET_ITINERARY_GENERATING', payload: false });
        }
    }, [state.drafts.tripPlanner, showNotification]);

    const handleMechanicSubmit = useCallback(async (e: FormEvent) => {
        e.preventDefault();
        if (state.mechanicMode === 'diagnose') {
            dispatch({ type: 'SET_DIAGNOSIS_GENERATING', payload: true });
            try {
                const diagnosis = await diagnoseProblem(
                    state.drafts.virtualMechanic.problemDescription,
                    state.activeVehicle!,
                    state.drafts.virtualMechanic.problemImage || undefined
                );
                dispatch({ type: 'SET_DIAGNOSIS', payload: { diagnosis, diagnosisId: null } });
            } catch (err) {
                showNotification("Errore nella diagnosi.", "error");
            } finally {
                dispatch({ type: 'SET_DIAGNOSIS_GENERATING', payload: false });
            }
        }
    }, [state.mechanicMode, state.drafts.virtualMechanic, state.activeVehicle, showNotification]);

    // ... (restanti handler CRUD)

    return (
        <AppContext.Provider value={{ state, dispatch, handleTripSubmit, handleMechanicSubmit, handleSendMessage }}>
            {children}
        </AppContext.Provider>
    );
};

export const useAppContext = () => useContext(AppContext);

import React, { Component, ErrorInfo, ReactNode } from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

// --- Error Boundary Component ---
interface ErrorBoundaryProps {
  // Made optional to satisfy strict attribute checks on usage <ErrorBoundary>...</ErrorBoundary>
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error?: Error;
}

// Fix: Explicitly importing and using Component<P, S> from React ensures that 'props' and 'state' properties are correctly inherited and typed, resolving the error where 'props' was not found on the ErrorBoundary instance.
class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  state: ErrorBoundaryState = {
    hasError: false,
    error: undefined,
  };

  constructor(props: ErrorBoundaryProps) {
    super(props);
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    // Update state so the next render will show the fallback UI.
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    // Log the error to an error reporting service
    console.error("Uncaught error:", error, errorInfo);
  }

  render(): ReactNode {
    // Fix: Accessing state which is now correctly inferred from the base Component class.
    if (this.state.hasError) {
      // Custom fallback UI
      return (
        <div className="bg-gray-900 text-white min-h-screen flex items-center justify-center font-sans p-4">
          <div className="bg-gray-800 p-8 rounded-lg shadow-xl text-center max-w-lg">
            <h1 className="text-2xl font-bold text-red-400 mb-4">Oops! Qualcosa è andato storto.</h1>
            <p className="text-gray-300 mb-6">
              Si è verificato un errore inaspettato. Prova a ricaricare la pagina. Se il problema persiste, contatta il supporto.
            </p>
            <pre className="bg-gray-700/50 p-4 rounded-md text-left text-sm text-red-300 overflow-auto mb-6" style={{ whiteSpace: 'pre-wrap', wordBreak: 'break-all' }}>
              {this.state.error?.toString()}
            </pre>
            <button
              onClick={() => window.location.reload()}
              className="px-6 py-2 font-semibold text-white bg-blue-600 rounded-md shadow-sm hover:bg-blue-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 transition-colors"
            >
              Ricarica Pagina
            </button>
          </div>
        </div>
      );
    }

    // Fix: Accessing props which is now correctly inferred from the base Component class.
    return this.props.children;
  }
}
// --- End Error Boundary Component ---

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <ErrorBoundary>
      <App />
    </ErrorBoundary>
  </React.StrictMode>
);

// --- PWA Service Worker Registration ---
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    // Use relative path with explicit scope to handle preview environments better
    navigator.serviceWorker.register('./service-worker.js', { scope: './' })
      .then((registration) => {
        console.log('ServiceWorker registration successful with scope: ', registration.scope);
      })
      .catch((error) => {
        console.log('ServiceWorker registration failed: ', error);
      });
  });
}

